import sys, os, base64

NETINFO = ''

def rd(p):
    return open(p, encoding='utf-8').read()

def rep(s, old, new, name):
    if s.count(old) != 1:
        print('NOT FOUND/AMBIGUOUS:', name)
        sys.exit(1)
    return s.replace(old, new, 1)

if os.path.exists('lib/netinfo.dart'):
    print('already patched'); sys.exit(0)
for need in ('lib/pubg.dart', 'lib/netcheck.dart'):
    if not os.path.exists(need):
        print('شغّل patch5_pubg_wifi.py أولًا (ينقص', need + ')'); sys.exit(1)

# ---- probe.dart ----
p = rd('lib/probe.dart')
p = rep(p, """  final int secs;
  ProbeRes(this.ok, this.reachable, this.band, this.rsrp, this.sinr, this.secs, this.note);
}
""", """  final int secs;
  final String cell, pci, earfcn;
  final bool ca;
  ProbeRes(this.ok, this.reachable, this.band, this.rsrp, this.sinr, this.secs, this.note,
      {this.cell = '', this.pci = '', this.earfcn = '', this.ca = false});
}

/// هل الراوتر يستخدم تجميع نطاقات (4G+)؟ يعتمد على نوع الشبكة 1011 أو حقول الخلية الثانوية إن وُجدت.
bool isCaMap(Map<String, String> st, Map<String, String> sig) {
  if ((st['CurrentNetworkTypeEx'] ?? '') == '1011') return true;
  for (final e in sig.entries) {
    final k = e.key.toLowerCase();
    if ((k.contains('scell') || k.startsWith('scc') || k.contains('ca_band')) &&
        e.value.isNotEmpty && e.value != '0' && e.value != '--') {
      return true;
    }
  }
  return false;
}
""", 'probe ProbeRes')

# ---- game.dart / download.dart ----
g = rd('lib/game.dart')
g = rep(g, "  final bool keepAwake;\n  GameCtl({", """  final bool keepAwake;
  final Future<Map<String, String>> Function()? snap;
  final Future<List<Map<String, String>>> Function()? hosts;
  final List<int> scanList;
  List<int> get scan => scanList.isNotEmpty ? scanList : sup;
  GameCtl({""", 'GameCtl fields')
g = rep(g, "    required this.keepAwake,\n  });", """    required this.keepAwake,
    this.snap,
    this.hosts,
    this.scanList = const <int>[],
  });""", 'GameCtl ctor')
g = rep(g, "bands: ctl.sup,", "bands: ctl.scan,", 'game bands')
g = rep(g, "total = ctl.sup.length + 4;", "total = ctl.scan.length + 4;", 'game total')
d = rd('lib/download.dart')
d = rep(d, "bands: ctl.sup,", "bands: ctl.scan,", 'download bands')
d = rep(d, "total = ctl.sup.length + 4;", "total = ctl.scan.length + 4;", 'download total')

# ---- main.dart ----
m = rd('lib/main.dart')
m = rep(m, "import 'modes.dart';\n", "import 'modes.dart';\nimport 'netinfo.dart';\n", 'main import')
m = rep(m, """        var connected = true;
        try {
          connected = Huawei.kv(await hw!.get('monitoring/status'))['ConnectionStatus'] == '901';
        } catch (_) {}
""", """        var connected = true;
        var stm = <String, String>{};
        try {
          stm = Huawei.kv(await hw!.get('monitoring/status'));
          connected = stm['ConnectionStatus'] == '901';
        } catch (_) {}
""", 'probe status')
m = rep(m, """    var good = 0;
    var lastBand = '';
    while (sw.elapsed < const Duration(seconds: 55)) {
""", """    var good = 0;
    var lastBand = '';
    var everApplied = false;
    while (sw.elapsed < const Duration(seconds: 55) && (everApplied || sw.elapsed < const Duration(seconds: 25))) {
""", 'probe loop')
m = rep(m, "final applied = norm(n['LTEBand'] ?? '') == norm(mask) && n['NetworkMode'] == mode;\n",
        "final applied = norm(n['LTEBand'] ?? '') == norm(mask) && n['NetworkMode'] == mode;\n        if (applied) everApplied = true;\n", 'applied')
m = rep(m, "return ProbeRes(true, true, 'B$b', r, num_(s['sinr']), sw.elapsed.inSeconds, '');",
        """return ProbeRes(true, true, 'B$b', r, num_(s['sinr']), sw.elapsed.inSeconds, '',
                cell: s['cell_id'] ?? '',
                pci: s['pci'] ?? '',
                earfcn: s['earfcn'] ?? s['dlearfcn'] ?? s['ltedlfreq'] ?? '',
                ca: isCaMap(stm, s));""", 'probe return')
m = rep(m, "final why = !reached ? 'الراوتر ما ردّ' : (lastBand.isEmpty ? 'ما سجّل على أي نطاق' : 'بقي على $lastBand');",
        "final why = !reached ? 'الراوتر ما ردّ' : (!everApplied ? 'الراوتر ما قبل هذا النطاق (غير مدعوم؟)' : (lastBand.isEmpty ? 'ما سجّل على أي نطاق' : 'بقي على $lastBand'));", 'why')
m = rep(m, "  GameCtl gameCtl() => GameCtl(\n", """  /// حالة الراوتر: الإشارة + الحالة العامة (الحقول المأخوذة من الحالة تبدأ بـ st_).
  Future<Map<String, String>> snapQuiet() async {
    final s = Huawei.kv(await hw!.get('device/signal'));
    var st = <String, String>{};
    try {
      st = Huawei.kv(await hw!.get('monitoring/status'));
    } catch (_) {}
    return <String, String>{...s, for (final e in st.entries) 'st_${e.key}': e.value};
  }

  /// الأجهزة المتصلة (واي فاي + سلك)، بدون تكرار.
  Future<List<Map<String, String>>> hostsQuiet() async {
    final out = <String, Map<String, String>>{};
    List<Map<String, String>> parse(String x) => <Map<String, String>>[
          for (final mm in RegExp(r'<Host>(.*?)</Host>', dotAll: true).allMatches(x)) Huawei.kv(mm[1]!)
        ];
    try {
      for (final h in parse(await hw!.get('wlan/host-list'))) {
        out[h['MacAddress'] ?? h['IpAddress'] ?? '${out.length}'] = <String, String>{...h, '_t': 'wifi'};
      }
    } catch (_) {}
    try {
      for (final h in parse(await hw!.get('lan/HostInfo'))) {
        if ((h['Active'] ?? '1') == '0') continue;
        out.putIfAbsent(h['MacAddress'] ?? h['IpAddress'] ?? '${out.length}',
            () => <String, String>{...h, '_t': (h['InterfaceType'] ?? '').toLowerCase().contains('wi') ? 'wifi' : 'lan'});
      }
    } catch (_) {}
    return out.values.toList();
  }

  GameCtl gameCtl() => GameCtl(
""", 'helpers')
m = rep(m, """        probe: probeQuiet,
        keepAwake: awake,
      );""", """        probe: probeQuiet,
        keepAwake: awake,
        snap: snapQuiet,
        hosts: hostsQuiet,
        scanList: (<int>{...sup, ...kSaudiBands}.toList()..sort()),
      );""", 'gameCtl')

# ---- modes.dart ----
md = rd('lib/modes.dart')
md = rep(md, "import 'game.dart';\n", "import 'game.dart';\nimport 'netinfo.dart';\n", 'modes import')
md = rep(md, "        body: ListView(padding: const EdgeInsets.all(12), children: [\n",
        """        body: ListView(padding: const EdgeInsets.all(12), children: [
          _tile(context, Icons.cell_tower, 'الشبكة والنطاقات',
              'الأبراج، تجميع النطاقات +، الأجهزة المتصلة، اختبار قصير وفحص شامل', NetInfoPage(ctl: ctl)),
""", 'modes tile')

for pth, s in (('lib/probe.dart', p), ('lib/game.dart', g), ('lib/download.dart', d), ('lib/main.dart', m), ('lib/modes.dart', md)):
    open(pth, 'w', encoding='utf-8').write(s)
open('lib/netinfo.dart', 'wb').write(base64.b64decode(NETINFO))
print('patched OK')
